const database = { getCustomerTier: (id) => (id === 'VIP1' ? 'VIP' : 'REGULAR') };

function calculateDiscount(customerId, amount) {
  const tier = database.getCustomerTier(customerId);
  return tier === 'VIP' ? amount * 0.8 : amount;
}

console.log(calculateDiscount('VIP1', 1000));

