function makeCounterMixed() {
  let count = 0;
  return () => {
    count += 1;
    return count;
  };
}

function makeCounterSeparated() {
  let count = 0;
  return {
    increment() { count += 1; },
    getCount() { return count; },
  };
}

const mixed = makeCounterMixed();
console.log(mixed(), mixed());

const separated = makeCounterSeparated();
separated.increment();
separated.increment();
console.log(separated.getCount());
console.log(separated.getCount());

